/*  apply / revert (Lot 7)                                                    */
/* -------------------------------------------------------------------------- */

/**
 * Exported (Lot 5 of the "rail application et boucle des leçons" chantier) so
 * `evalsReconciler.ts`'s `applyResultSideEffects` can build the SAME
 * `ApplyContext` for an `improvementDiff` result at import time, without
 * duplicating this env-var reading anywhere else. This does NOT reopen the
 * module-boundary rule this file's header documents (`evals.ts` never imports
 * `evalsReconciler.ts`) — the dependency here runs the other way:
 * `evalsReconciler.ts` imports THIS symbol from `evals.ts`, which stays a
 * one-directional edge since `evals.ts` never imports back from
 * `evalsReconciler.ts` as an ES module (only `Bun.spawnSync`s it).
 *
 * Builds the `ApplyContext` from environment variables — NEVER a hardcoded
 * default pointing at a real `~/.claude/skills/*` path (see apply.ts's file
 * header and the Lot 7 guard-rail). A target is only populated when ALL of
 * its required env vars are set; `applyProposal`/`revertProposal` then throw
 * a clear error if the proposal's skill needs a target that is missing.
 */
export function applyContextFromEnv(): ApplyContext {
  const ctx: ApplyContext = {};

  const skillsRemote = process.env.WORKSTATION_SKILLS_REPO_REMOTE;
  const skillsIntegrationClone = process.env.WORKSTATION_SKILLS_INTEGRATION_CLONE;
  const skillsInstallRoot = process.env.WORKSTATION_SKILLS_INSTALL_ROOT;
  if (skillsRemote && skillsIntegrationClone && skillsInstallRoot) {
    ctx.skillRepo = {
      remote: skillsRemote,
      integrationClone: skillsIntegrationClone,
      installRoot: skillsInstallRoot,
    };
  }

  const metaGovernRemote = process.env.WORKSTATION_METAGOVERN_REPO_REMOTE;
  const metaGovernIntegrationClone = process.env.WORKSTATION_METAGOVERN_INTEGRATION_CLONE;
  const metaGovernLocalClone = process.env.WORKSTATION_METAGOVERN_LOCAL_CLONE;
  if (metaGovernRemote && metaGovernIntegrationClone && metaGovernLocalClone) {
    ctx.metaGovernRepo = {
      remote: metaGovernRemote,
      integrationClone: metaGovernIntegrationClone,
      localClone: metaGovernLocalClone,
    };
  }

  return ctx;
}

async function cmdApply(proposalId: string) {
  const outcome = await applyProposal(proposalId, applyContextFromEnv());
  switch (outcome.kind) {
    case 'pending':
      process.stdout.write(
        `VERDICT: PENDING\nGate ${outcome.proposal.gateRef} n'a pas encore de réponse — rien n'a bougé.\n`,
      );
      break;
    case 'rejected':
      process.stdout.write(
        `VERDICT: REJECTED\nProposal ${outcome.proposal.id} rejetée — branche supprimée, main intact, rien installé.\n`,
      );
      break;
    case 'changes_requested':
      process.stdout.write(
        `VERDICT: CHANGES_REQUESTED\nAncienne proposal ${outcome.proposal.id} close — nouvelle proposal ` +
          `${outcome.supersededBy.id} (v${outcome.supersededBy.version}) créée, gate ${outcome.newGateRef}.\n`,
      );
      break;
    case 'rebase_needed':
      process.stdout.write(
        `VERDICT: REBASE_NEEDED\n${outcome.reason}\nChip ouvert : ${outcome.chip.id}\n`,
      );
      break;
    case 'applied':
      process.stdout.write(
        `VERDICT: APPLIED\nProposal ${outcome.proposal.id} appliquée — mergeSha ${outcome.proposal.mergeSha}\n`,
      );
      break;
  }
}

async function cmdRevert(proposalId: string) {
  const outcome = await revertProposal(proposalId, applyContextFromEnv());
  if (outcome.kind === 'rebase_needed') {
    process.stdout.write(
      `VERDICT: REBASE_NEEDED\n${outcome.reason}\nChip ouvert : ${outcome.chip.id}\n`,
    );
    return;
  }
  process.stdout.write(`VERDICT: REVERTED\nProposal ${outcome.proposal.id} revert effectué.\n`);
}

/**
 * `evals rebase-refresh <proposalId>` — the CLI wiring `refreshBeforeSha`'s
 * own docstring (server/services/reviews/apply.ts) points to: the ONLY
 * legitimate way to unstick a proposal permanently wedged in `rebase_needed`
 * by the §11 #17 guard (beforeSha vs the target's real HEAD). Meant to be run
 * AFTER a human has confirmed the proposal's branch is still valid despite
 * the divergence (the chip a `rebase_needed` outcome opens spells this out) —
 * this command itself does not ask for that confirmation, it only performs
 * the mechanical resolve-then-advance once a human has decided to run it.
 *
 * Resolves the new beforeSha via `resolveCurrentMainSha` (the real,
 * currently-fetched HEAD of the target's `main` — same git primitives
 * `applyProposal`'s own §11 #17 check uses, reused rather than duplicated),
 * then calls the already-exported `refreshBeforeSha(proposalId, newBeforeSha)`
 * — no proposal-mutation logic lives in this CLI file, same thin-wrapper
 * pattern as `cmdApply`/`cmdRevert` above.
 */
async function cmdRebaseRefresh(proposalId: string) {
  const ctx = applyContextFromEnv();

  const before = await getImprovementProposal(proposalId);
  if (!before) fail(`ImprovementProposal introuvable : ${proposalId}`);
  const previousBeforeSha = before.beforeSha;

  const newBeforeSha = await resolveCurrentMainSha(proposalId, ctx);
  const updated = await refreshBeforeSha(proposalId, newBeforeSha);

  process.stdout.write(
    `VERDICT: REBASE_REFRESHED\n` +
      `Proposal ${updated.id}\n` +
      `Ancien beforeSha : ${previousBeforeSha}\n` +
      `Nouveau beforeSha : ${updated.beforeSha}\n` +
      `Prochaine étape : cd ~/Desktop/my-projets/workstation && bun run evals apply ${updated.id}\n`,
  );
}

