file.content:
 * — nothing else on `main` can ever be touched by this function, no matter
 * what the branch contains elsewhere. `git rm -r` (drop the skill folder's
 * current content from the index) + `git checkout <branch> -- <skill>/`
 * (restore it from the branch tip — works regardless of ancestry, `checkout
 * -- <pathspec>` reads tree objects directly and never consults history) +
 * `git add -A` builds the new tree; `git write-tree` + `git commit-tree -p
 * <mainSha> -p <branchSha>` then hand-builds a real TWO-PARENT commit so the
 * result is indistinguishable, to every other piece of this file, from a
 * normal `--no-ff` merge commit — in particular `revertMergeCommitOnMain`'s
 * `git revert -m 1`, which requires an actual merge commit to work at all
 * (verified empirically against a hand-built `commit-tree` merge commit
 * before wiring this in).
 *
 * Path-safety guard duplicated here (not just relied upon downstream in
 * `installSkillFromIntegrationClone`): this function is the FIRST place a
 * path derived from `proposal.skill` is used destructively (`git rm -r`)
 * against the REAL `target.remote`, earlier than the local install step —
 * without this guard, a skill name that is git-ref-SAFE (e.g. contains `/`,
 * which git allows in a ref but `isSafeSegment` rejects as a directory
 * traversal risk) could reach `git rm -r`/`git checkout -- <path>` here and
 * mutate the REAL remote's `main` before the local-install guard ever got a
 * chance to refuse it.
 */

/**
 * Shared skill-name guard for BOTH `graftSkillContent` (git pathspecs
 * against the REAL remote) and `installSkillFromIntegrationClone` (fs paths)
 * — see each call site's own comment for the specific risk each clause
 * closes. The trailing `startsWith(':')` clause is correctif #2 (revue
 * adversariale du 2026-07-30, P1/state-safety — "LE PLUS SÉVÈRE"):
 * `proposal.skill` is an open `z.string().min(1)` (src/types/review.ts),
 * filled from a cloud round's `results.json` and explicitly treated as
 * adversarial input by this module's own docstring. `isSafeSegment`
 * (server/services/slug.ts) rejects `/`, `\`, `..` and control characters,
 * but has NO notion of git's "pathspec magic" syntax — a pathspec whose
 * FIRST character is `:` is interpreted specially (e.g. `:(exclude)...`,
 * `:(glob)...`), never as a literal path. Reproduced empirically: with
 * `proposal.skill = ':(exclude)nonexistent'`, `skillPath` becomes
 * `':(exclude)nonexistent/'`; passed as-is to `git rm -r --ignore-unmatch --
 * $skillPath` (no other positive pathspec present) stages the deletion of
 * EVERY tracked file in the repo, `git add -A -- $skillPath` re-stages the
 * now-empty working tree, and `git write-tree` yields git's canonical EMPTY
 * tree (`4b825dc642cb6eb9a060e54bf8d69288fbee4904`) — every command exits 0,
 * so NO failure path is triggered, and the resulting two-parent commit
 * (a completely empty repo) is pushed unconditionally to the real remote's
 * `main`. Rejecting a leading `:` outright closes this off before any git
 * command ever sees the value. `GIT_LITERAL_PATHSPEC_ENV` below is the
 * SECOND, independent layer (defense in depth): even a value that somehow
 * bypassed this guard could no longer be interpreted as pathspec magic by
 * the three git calls in `graftSkillContent` that take `skillPath` as an
 * argument.
 */
function isUnsafeSkillSegment(skill: string): boolean {
  return (
    !isSafeSegment(skill) ||
    skill === '.' ||
    path.posix.normalize(skill) === '.' ||
    path.posix.normalize(skill) === '' ||
    skill.startsWith(':')
  );
}

/**
 * Forces git to treat every pathspec of the subprocess it is passed to as a
 * LITERAL path segment — never as pathspec "magic" (glob or the `:(...)`/
 * `:!`/`:^` short forms). Defense in depth alongside `isUnsafeSkillSegment`'s
 * explicit leading-`:` rejection above (correctif #2): merged into the `env`
 * of the three `graftSkillContent` git calls that take `skillPath` as a
 * pathspec argument (`rm`, `checkout -- <path>`, `add -A --`), so a crafted
 * `proposal.skill` can never be interpreted as anything other than a literal
 * directory name by those calls, guard or no guard. Verified empirically:
 * `GIT_LITERAL_PATHSPECS=1 git rm -r --ignore-unmatch -- ':(exclude)nonexistent/'`
 * looks for a LITERAL path named `:(exclude)nonexistent/` (which does not
 * exist — `--ignore-unmatch` makes that a no-op) instead of expanding the
 * magic exclude pattern, leaving the rest of the tree untouched.
 */
const GIT_LITERAL_PATHSPEC_ENV: ExtraEnv = { GIT_LITERAL_PATHSPECS: '1' };

function graftSkillContent(
  proposal: ImprovementProposal,
  target: RepoIntegrationTarget,
  branch: string,
  mainSha: string,
  branchSha: string,
): { ok: true; mergeSha: string } | { ok: false; reason: string; cause: MergeFailureCause } {
  const cwd = target.integrationClone;

  if (isUnsafeSkillSegment(proposal.skill)) {
    return {
      ok: false,
      cause: 'unsafe-skill-name',
      reason:
        'nom de skill non sûr pour une opération fichier (traversée de chemin, séparateur, segment ' +
        '"." qui résoudrait le chemin greffé à la racine du dépôt, ou premier caractère ":" — magie de ' +
        `pathspec git) : ${JSON.stringify(proposal.skill)} — greffe refusée avant tout git rm/checkout sur ` +
        'le remote réel',
    };
  }
  const skillPath = `${proposal.skill}/`;

  // finding P1 (round revue adversariale 2026-07-30, correctif #3) — decide
  // BEFORE any mutation whether the branch's absence of `<skill>/` is a
  // legitimate deletion or a suspicious accident (empty/failed cloud job,
  // wrong skill name). `mainHasPath` is checked FIRST, alongside
  // `branchHasPath`, so this function never has to infer intent from a
  // half-mutated index — see the guard just below for the actual decision.
  const mainHasPath = gitTry(['rev-parse', '--verify', '--quiet', `${mainSha}:${skillPath}`], cwd).ok;
  const branchHasPath = gitTry(['rev-parse', '--verify', '--quiet', `${branch}:${skillPath}`], cwd).ok;

  // `main` currently has real content at `<skill>/` but the branch has NONE
  // at all — the file header's assumption ("un chemin absent sur la branche
  // signifie que la branche supprime légitimement tout le dossier") used to
  // be taken on faith. Nothing upstream of this function actually confirms
  // that: `scopeLintViolation` (server/cli/evalsReconciler.ts) only checks
  // that DECLARED `changedPaths` stay inside `<skill>/` — an empty or wrong
  // `changedPaths` array passes it without complaint — and the human-facing
  // gate text is built from those SAME self-declared fields, never a real
  // diff, so an approver has no way to notice the branch is actually empty
  // for this skill. This function has no channel today to receive a
  // POSITIVE confirmation of intentional deletion (the frozen
  // `ImprovementProposal` schema — src/types/review.ts — carries no
  // `changedPaths`), so rather than infer intent from absence, it refuses
  // and routes to a human via a rebase chip — exactly like every other
  // guard in this module. A real, deliberate skill-folder deletion is still
  // possible; a human confirms it explicitly (re-approving after
  // inspection, or rebasing) instead of it happening silently on the first
  // pass.
  if (mainHasPath && !branchHasPath) {
    return {
      ok: false,
      cause: 'skill-folder-missing-from-branch',
      reason:
        `la branche ${branch} ne contient AUCUN fichier sous ${skillPath} alors que main en a — ` +
        'suppression non confirmée (aucun changedPaths énumérant les fichiers supprimés accessible à ' +
        'ce niveau) : greffe refusée avant tout git rm/checkout sur le remote réel, pour éviter ' +
        "qu'un job cloud vide/raté n'efface silencieusement le contenu réel du skill",
    };
  }

  // Drop whatever `<skill>/` currently holds on `main` — `--ignore-unmatch`:
  // a brand-new skill with no prior folder on main is not an error.
  // `GIT_LITERAL_PATHSPEC_ENV` — see its own docstring (correctif #2).
  const rmResult = gitTry(['rm', '-r', '--ignore-unmatch', '-q', '--', skillPath], cwd, GIT_LITERAL_PATHSPEC_ENV);
  if (!rmResult.ok) {
    resetHardBestEffort(cwd, mainSha);
    return {
      ok: false,
      cause: 'graft-failed',
      reason: `git rm -r ${skillPath} a échoué dans ${cwd} : ${rmResult.stderr || rmResult.stdout || 'sortie vide'}`,
    };
  }

  // Restore `<skill>/` from the branch tip when it has one (checked above,
  // via `mainHasPath`/`branchHasPath`) — a branch with no path here either
  // already passed the guard above (nothing on main to lose) or legitimately
  // has nothing to restore.
  if (branchHasPath) {
    const checkoutResult = gitTry(['checkout', branch, '--', skillPath], cwd, GIT_LITERAL_PATHSPEC_ENV);
    if (!checkoutResult.ok) {
      resetHardBestEffort(cwd, mainSha);
      return {
        ok: false,
        cause: 'graft-failed',
