  test('greffe de contenu (chemin A) : une branche improve/* SANS ancêtre commun (instantané cloud réel) est appliquée avec succès', async () => {
    await freshRoot();
    const fxRoot = await freshFixtureDir();
    const skill = 'orphan-history-skill';

    const bareRepo = path.join(fxRoot, 'remote.git');
    await initBareRepo(bareRepo);
    const beforeSha = await initMainBranch(bareRepo, {
      [`${skill}/SKILL.md`]: 'v1\n',
      [`${skill}/stale.md`]: 'à supprimer par la greffe\n',
      'other-skill/SKILL.md': 'ne doit jamais être touché\n',
    });

    const { proposal, branch, gateRef } = await applyMod.createGatedProposal(
      baseGateInput({ skill, beforeSha }),
    );

    // The cloud's snapshot for this skill DROPS `stale.md` and REPLACES
    // `SKILL.md` — no shared ancestry with `bareRepo` at all.
    const branchSha = await pushOrphanSnapshotBranch(bareRepo, branch, {
      [`${skill}/SKILL.md`]: 'v2 — améliorée par la routine cloud\n',
      [`${skill}/NEWFILE.md`]: 'fichier ajouté par la routine cloud\n',
    });
    // Confirm the fixture really reproduces the bug's signature: NO common
    // ancestor (`git merge-base` exits non-zero when none exists).
    let hasMergeBase = true;
    try {
      gitOut(['merge-base', 'main', branch], bareRepo);
    } catch {
      hasMergeBase = false;
    }
    expect(hasMergeBase).toBe(false);
    await answerGate(gateRef, 'approved');

    const installRoot = path.join(fxRoot, 'install-root');
    const ctx: ApplyContext = {
      skillRepo: { remote: bareRepo, integrationClone: path.join(fxRoot, 'ic'), installRoot },
    };

    const outcome = await applyMod.applyProposal(proposal.id, ctx);
    expect(outcome.kind).toBe('applied');
    if (outcome.kind !== 'applied') throw new Error('unreachable');

    const mergeSha = outcome.proposal.mergeSha;
    if (!mergeSha) throw new Error('mergeSha manquant');

    // Real two-parent commit — `revertMergeCommitOnMain`'s `git revert -m 1`
    // depends on this shape.
    const parents = gitOut(['log', '-1', '--format=%P', mergeSha], bareRepo).split(/\s+/);
    expect(parents).toEqual([beforeSha, branchSha]);

    // Content scoped EXACTLY to `<skill>/` — nothing else on main moved.
    expect(gitOut(['show', `${mergeSha}:${skill}/SKILL.md`], bareRepo)).toBe(
      'v2 — améliorée par la routine cloud',
    );
    expect(gitOut(['show', `${mergeSha}:${skill}/NEWFILE.md`], bareRepo)).toBe(
      'fichier ajouté par la routine cloud',
    );
    expect(
      gitOut(['ls-tree', '-r', '--name-only', mergeSha, '--', `${skill}/stale.md`], bareRepo),
    ).toBe('');
    expect(gitOut(['show', `${mergeSha}:other-skill/SKILL.md`], bareRepo)).toBe(
      'ne doit jamais être touché',
    );

    // The local install picked up the same content.
    const installed = await readFile(path.join(installRoot, skill, 'SKILL.md'), 'utf8');
    expect(installed).toBe('v2 — améliorée par la routine cloud\n');
  });

