test('correctif #2c — défense en profondeur GIT_LITERAL_PATHSPECS : câblage vérifié par lecture de source, primitive vérifiée empiriquement', async () => {
  // Partie 1 (câblage) : les TROIS appels git de `graftSkillContent` qui
  // prennent `skillPath` comme pathspec (rm/checkout/add) doivent tous les
  // trois porter `GIT_LITERAL_PATHSPEC_ENV`.
  const source = await readFile(path.join(import.meta.dir, 'apply.ts'), 'utf8');
  const rmCall = source.match(/gitTry\(\['rm', '-r', '--ignore-unmatch', '-q', '--', skillPath\], cwd, ([A-Za-z_]+)\)/);
  const checkoutCall = source.match(/gitTry\(\['checkout', branch, '--', skillPath\], cwd, ([A-Za-z_]+)\)/);
  const addCall = source.match(/gitTry\(\['add', '-A', '--', skillPath\], cwd, ([A-Za-z_]+)\)/);
  expect(rmCall?.[1]).toBe('GIT_LITERAL_PATHSPEC_ENV');
  expect(checkoutCall?.[1]).toBe('GIT_LITERAL_PATHSPEC_ENV');
  expect(addCall?.[1]).toBe('GIT_LITERAL_PATHSPEC_ENV');

  // Partie 2 (primitive) : reproduction empirique — même si le garde
  // explicite (correctif #2b) était contourné, `GIT_LITERAL_PATHSPECS=1`
  // empêche à lui seul la magie de pathspec de vider tout l'arbre. Rejoue
  // EXACTEMENT la séquence de `graftSkillContent` (rm --ignore-unmatch,
  // add -A, write-tree) sur un dépôt jetable, en dehors de apply.ts, avec
  // et sans la variable d'environnement.
  const fxRoot = await freshFixtureDir();
  const repo = path.join(fxRoot, 'literal-pathspec-repro');
  git(['init', '-q', '-b', 'main', repo]);
  git(['config', 'user.email', 'fixture@workstation.local'], repo);
  git(['config', 'user.name', 'fixture'], repo);
  await writeFiles(repo, {
    'skillA/file.txt': 'skillA contenu réel\n',
    'skillB/file.txt': 'skillB contenu réel\n',
  });
  git(['add', '-A'], repo);
  git(['commit', '-q', '-m', 'init'], repo);
  const originalTree = gitOut(['rev-parse', 'HEAD^{tree}'], repo);

  const magicSkillPath = ':(exclude)nonexistent/';

  // SANS la variable — reproduit le défaut brut : arbre vidé.
  execFileSync('git', ['rm', '-r', '--ignore-unmatch', '-q', '--', magicSkillPath], { cwd: repo });
  execFileSync('git', ['add', '-A', '--', magicSkillPath], { cwd: repo });
  const emptiedTree = gitOut(['write-tree'], repo);
  expect(emptiedTree).toBe('4b825dc642cb6eb9a060e54bf8d69288fbee4904'); // arbre vide canonique de git

  // Restaure l'état propre avant de rejouer AVEC la protection.
  git(['reset', '--hard', 'HEAD'], repo);
  expect(gitOut(['rev-parse', 'HEAD^{tree}'], repo)).toBe(originalTree);

  // AVEC GIT_LITERAL_PATHSPECS=1 — même séquence, exactement l'environnement
  // que `graftSkillContent` applique maintenant à ces trois commandes.
  // `git rm --ignore-unmatch` sur le chemin littéral (qui n'existe pas)
  // reste un no-op silencieux (comportement voulu de --ignore-unmatch) ;
  // mais `git add -A` sur ce MÊME chemin littéral introuvable, LUI, refuse
  // explicitement ("did not match any files", exit 128) au lieu de vider
  // l'arbre — c'est exactement `addResult.ok === false` dans
  // `graftSkillContent` (cause 'graft-failed', reset best-effort, main
  // jamais poussé) : un échec SÛR et typé plutôt qu'un vidage silencieux.
  const literalEnv = { ...process.env, GIT_LITERAL_PATHSPECS: '1' };
  execFileSync('git', ['rm', '-r', '--ignore-unmatch', '-q', '--', magicSkillPath], {
    cwd: repo,
    env: literalEnv,
    stdio: 'ignore',
  });
  let addRefused = false;
  try {
    execFileSync('git', ['add', '-A', '--', magicSkillPath], { cwd: repo, env: literalEnv, stdio: 'ignore' });
  } catch {
    addRefused = true;
  }
  expect(addRefused).toBe(true);

  // Quoi qu'il en soit (rm no-op, add refusé) — l'arbre n'a JAMAIS bougé :
  // aucune commande de cette séquence protégée n'a pu produire l'arbre vide.
  const protectedTree = gitOut(['write-tree'], repo);
  expect(protectedTree).toBe(originalTree);
  expect(protectedTree).not.toBe('4b825dc642cb6eb9a060e54bf8d69288fbee4904');
});

test('correctif #3 — branche orpheline SANS <skill>/ alors que main a du contenu réel -> rebase_needed (jamais une suppression silencieuse)', async () => {
  // NOTE sur la fidélité de ce fixture : quand le dossier `<skill>/` est
  // ENTIÈREMENT vide après le `git rm -r` interne (aucun fichier suivi NI
  // non suivi ne subsiste), `git add -A -- <skill>/` refuse tout seul
  // ("pathspec did not match any files", vérifié empiriquement) — un filet
  // de sécurité ACCIDENTEL de git, pas une garantie. Pour reproduire le
test('correctif #4 — les 3 resets --hard de nettoyage de graftSkillContent sont enveloppés best-effort (resetHardBestEffort)', async () => {
  // Simuler un ÉCHEC du `git reset --hard` de nettoyage lui-même (tout en
  // gardant les étapes PRÉCÉDENTES du graft réussies, pour isoler
  // précisément ce cleanup) exigerait de faire échouer un SEUL sous-process
  // git au milieu d'une séquence par ailleurs saine — irréalisable de
  // façon fiable/déterministe de l'extérieur sans monkey-patcher
  // `execFileSync` (le process de test tuerait alors sa propre capacité à
  // vérifier le comportement réel). Deux preuves à la place, comme pour
  // correctif #2c ci-dessus :
  //  1. lecture de source : les 3 occurrences de nettoyage dans
  //     `graftSkillContent` appellent bien `resetHardBestEffort`, jamais
  //     `git(['reset', '--hard', ...])` directement ;
  //  2. preuve empirique que la primitive SANS enveloppe lève bel et bien
  //     (`git reset --hard` sur un sha inexistant) — donc que l'enveloppe
  //     n'est pas un no-op mais corrige un vrai risque.
  const source = await readFile(path.join(import.meta.dir, 'apply.ts'), 'utf8');

  const graftMatch = source.match(/function graftSkillContent\([\s\S]*?\n}\n/);
  expect(graftMatch).not.toBeNull();
  const graftBody = graftMatch?.[0] ?? '';

  // Aucun reset --hard NU (non enveloppé) ne subsiste dans graftSkillContent —
  // seule l'issue de SUCCÈS (`reset --hard commitSha`) reste un appel direct,
  // les 3 issues d'ÉCHEC passent par le wrapper best-effort.
  const rawResetCount = (graftBody.match(/git\(\['reset', '--hard', /g) ?? []).length;
  const wrappedResetCount = (graftBody.match(/resetHardBestEffort\(cwd, mainSha\)/g) ?? []).length;
  expect(rawResetCount).toBe(1); // uniquement le reset --hard commitSha du chemin succès
  // 4 branches d'échec dans graftSkillContent (rm / checkout / add / write-tree-commit-tree) —
  // le brief en nomme 3 par leur nom ("git rm, git checkout, write-tree/commit-tree") mais le
  // code en a bien 4 (add -A a sa propre branche d'échec) ; les 4 sont enveloppées ici.
  expect(wrappedResetCount).toBe(4);

  // Preuve empirique que la primitive nue lève réellement.
  const fxRoot = await freshFixtureDir();
  const repo = path.join(fxRoot, 'reset-failure-repro');
  git(['init', '-q', '-b', 'main', repo]);
  git(['config', 'user.email', 'fixture@workstation.local'], repo);
  git(['config', 'user.name', 'fixture'], repo);
  await writeFiles(repo, { 'file.txt': 'v1\n' });
  git(['add', '-A'], repo);
  git(['commit', '-q', '-m', 'init'], repo);

  const bogusSha = '0000000000000000000000000000000000dead';
  expect(() => execFileSync('git', ['reset', '--hard', bogusSha], { cwd: repo, stdio: 'ignore' })).toThrow();
});

