test('correctif #4 — les 3 resets --hard de nettoyage de graftSkillContent sont enveloppés best-effort (resetHardBestEffort)', async () => {
  // Simuler un ÉCHEC du `git reset --hard` de nettoyage lui-même (tout en
  // gardant les étapes PRÉCÉDENTES du graft réussies, pour isoler
  // précisément ce cleanup) exigerait de faire échouer un SEUL sous-process
  // git au milieu d'une séquence par ailleurs saine — irréalisable de
  // façon fiable/déterministe de l'extérieur sans monkey-patcher
  // `execFileSync` (le process de test tuerait alors sa propre capacité à
  // vérifier le comportement réel). Deux preuves à la place, comme pour
  // correctif #2c ci-dessus :
  //  1. lecture de source : les 3 occurrences de nettoyage dans
  //     `graftSkillContent` appellent bien `resetHardBestEffort`, jamais
  //     `git(['reset', '--hard', ...])` directement ;
  //  2. preuve empirique que la primitive SANS enveloppe lève bel et bien
  //     (`git reset --hard` sur un sha inexistant) — donc que l'enveloppe
  //     n'est pas un no-op mais corrige un vrai risque.
  const source = await readFile(path.join(import.meta.dir, 'apply.ts'), 'utf8');

  const graftMatch = source.match(/function graftSkillContent\([\s\S]*?\n}\n/);
  expect(graftMatch).not.toBeNull();
  const graftBody = graftMatch?.[0] ?? '';

  // Aucun reset --hard NU (non enveloppé) ne subsiste dans graftSkillContent —
  // seule l'issue de SUCCÈS (`reset --hard commitSha`) reste un appel direct,
  // les 3 issues d'ÉCHEC passent par le wrapper best-effort.
  const rawResetCount = (graftBody.match(/git\(\['reset', '--hard', /g) ?? []).length;
  const wrappedResetCount = (graftBody.match(/resetHardBestEffort\(cwd, mainSha\)/g) ?? []).length;
  expect(rawResetCount).toBe(1); // uniquement le reset --hard commitSha du chemin succès
  // 4 branches d'échec dans graftSkillContent (rm / checkout / add / write-tree-commit-tree) —
  // le brief en nomme 3 par leur nom ("git rm, git checkout, write-tree/commit-tree") mais le
  // code en a bien 4 (add -A a sa propre branche d'échec) ; les 4 sont enveloppées ici.
  expect(wrappedResetCount).toBe(4);

  // Preuve empirique que la primitive nue lève réellement.
  const fxRoot = await freshFixtureDir();
  const repo = path.join(fxRoot, 'reset-failure-repro');
  git(['init', '-q', '-b', 'main', repo]);
  git(['config', 'user.email', 'fixture@workstation.local'], repo);
  git(['config', 'user.name', 'fixture'], repo);
  await writeFiles(repo, { 'file.txt': 'v1\n' });
  git(['add', '-A'], repo);
  git(['commit', '-q', '-m', 'init'], repo);

  const bogusSha = '0000000000000000000000000000000000dead';
  expect(() => execFileSync('git', ['reset', '--hard', bogusSha], { cwd: repo, stdio: 'ignore' })).toThrow();
});

